'use client';

import { useQuery } from '@tanstack/react-query';
import { api } from '@/lib/api';

/**
 * Shown on every app screen when the API runs with DEMO_MODE. The wallet graph, flagged positions, radar and track record
 * are then generated by the scorer from a synthetic world and must never be mistaken for real wallets. Markets, prices,
 * trades and settlements stay real Solana devnet data.
 */
export function DemoRibbon() {
  const health = useQuery({ queryKey: ['health-demo'], queryFn: api.health, staleTime: 5 * 60_000, retry: false });
  if (!health.data?.demoMode) return null;
  return (
    <div data-component="DemoRibbon" role="note" className="border-b border-white/10 bg-[rgba(139,92,246,0.14)] px-4 py-1.5 text-center text-xs text-white/80">
      <span className="font-semibold text-white">Demo data</span>
      {' '}for the smart-money radar: flagged wallets, positions and track record are synthetic. Markets, prices, trades and settlements are real Solana devnet.
    </div>
  );
}
